(function() {
  const btnReality = document.getElementById('btn-reality-mode');
  const btnReset = document.getElementById('btn-reset');
  const display = document.getElementById('reality-check-display');

  // Data derived strictly from S037 (p.12) limitations section
  const limitationsData = [
    {
      id: 'limit_sample',
      icon: '⚠',
      title: '样本自选择 (Self-Selected)',
      desc: '样本来源于自愿参与在线平台的用户，虽经事后分层分析校正，仍非严格随机抽样，不能保证完全代表各国人口统计学特征。',
      status: '未知变量'
    },
    {
      id: 'limit_certainty',
      icon: '⚠',
      title: '确定性假设 (Deterministic)',
      desc: '为保持实验可处理性，角色分类和生死结果被设定为 100% 确定，未包含现实自动驾驶技术中的感知不确定性。',
      status: '未知变量'
    },
    {
      id: 'limit_relations',
      icon: '⚠',
      title: '亲属关系缺失 (Relations)',
      desc: '实验未操纵受访者与受试角色之间的亲属或社会关系变量。此前仅在美国样本中测试过该变量，全球范围内的影响尚不明确。',
      status: '未知变量'
    },
    {
      id: 'limit_abstract',
      icon: '⚠',
      title: '抽象偏好基线 (Abstract Baseline)',
      desc: '数据反映的是 AV 部署前的抽象偏好。实际事故发生后，公众讨论将转向具体受害者，心理负担变化可能导致偏好偏移。',
      status: '未知变量'
    }
  ];

  let isExpanded = false;

  function renderChecks() {
    display.innerHTML = '';
    limitationsData.forEach((item, index) => {
      const div = document.createElement('div');
      div.className = 'status-item';
      div.innerHTML = `
        <span class="status-icon">${item.icon}</span>
        <div>
          <strong>${item.title}</strong>: ${item.desc}
          <div style="color: var(--warm); font-size: 12px; margin-top: 2px;">状态：${item.status}</div>
        </div>
      `;
      display.appendChild(div);

      // Staggered animation
      setTimeout(() => {
        div.classList.add('visible');
      }, index * 200);
    });
  }

  function resetDisplay() {
    display.innerHTML = '<div class="status-item default" style="opacity:1; transform:none;">等待检查...</div>';
    isExpanded = false;
  }

  if (btnReality) {
    btnReality.addEventListener('click', function() {
      if (!isExpanded) {
        renderChecks();
        isExpanded = true;
      }
    });
  }

  if (btnReset) {
    btnReset.addEventListener('click', resetDisplay);
  }
})();
